static lv_color_t bg(){return lv_color_hex(dark?INK:0xF9F9FB);}static lv_color_t surface(){return lv_color_hex(dark?0x1D1D2A:0xFFFFFF);}static lv_color_t text(){return lv_color_hex(dark?0xF8F7FA:0x18172E);}static lv_color_t muted(){return lv_color_hex(dark?0x92919E:0x747387);}static lv_color_t line(){return lv_color_hex(dark?0x333240:0xE6E4EA);}
static lv_obj_t* lab(lv_obj_t*p,const char*s,int x,int y,const lv_font_t*f,lv_color_t c){lv_obj_t*o=lv_label_create(p);lv_label_set_text(o,s);lv_obj_set_pos(o,x,y);lv_obj_set_style_text_font(o,f,0);lv_obj_set_style_text_color(o,c,0);return o;}
