static void bar(lv_obj_t*s){lab(s,"09:41",15,9,&lv_font_montserrat_12,text());lab(s,"WiFi  [|||]",244,9,&lv_font_montserrat_10,text());}
static void head(lv_obj_t*s,const char*step,const char*title,const char*sub){lab(s,step,20,46,&lv_font_montserrat_10,lv_color_hex(RED));lab(s,title,20,65,&lv_font_montserrat_24,text());lv_obj_t*l=lab(s,sub,20,99,&lv_font_montserrat_12,muted());lv_obj_set_width(l,275);lv_label_set_long_mode(l,LV_LABEL_LONG_WRAP);}
