static lv_obj_t* bottom(lv_obj_t*s,const char*t,lv_event_cb_t cb){lv_obj_t*b=lv_btn_create(s);lv_obj_set_size(b,280,42);lv_obj_align(b,LV_ALIGN_BOTTOM_MID,0,-20);btnstyle(b,true);lv_obj_add_event_cb(b,cb,LV_EVENT_CLICKED,NULL);lv_obj_t*l=lv_label_create(b);lv_label_set_text(l,t);lv_obj_center(l);return b;}
