static void theme_cb(lv_event_t*e){dark=(bool)(intptr_t)lv_event_get_user_data(e);show_wifi();}
static void themebtn(lv_obj_t*s,const char*t,const char*sub,int y,bool d){lv_obj_t*b=lv_btn_create(s);lv_obj_set_pos(b,20,y);lv_obj_set_size(b,280,58);lv_obj_set_style_radius(b,13,0);lv_obj_set_style_bg_color(b,lv_color_hex(0x272632),0);lv_obj_set_style_border_width(b,1,0);lv_obj_set_style_border_color(b,lv_color_hex(0x45434F),0);lv_obj_add_event_cb(b,theme_cb,LV_EVENT_CLICKED,(void*)(intptr_t)d);lab(b,t,18,8,&lv_font_montserrat_14,lv_color_hex(0xFFFFFF));lab(b,sub,18,29,&lv_font_montserrat_10,lv_color_hex(0x92919E));lab(b,">",250,17,&lv_font_montserrat_14,lv_color_hex(0x92919E));}
static void boot(){dark=true;lv_obj_t*s=screen();bar(s);lab(s,"flap",70,78,&lv_font_montserrat_32,lv_color_hex(YELLOW));lab(s,"py",151,78,&lv_font_montserrat_32,lv_color_hex(RED));lab(s,"CREATED BY  INV3RSE",108,130,&lv_font_montserrat_10,lv_color_hex(0xA09EAA));lab(s,"ANTES DE COMENZAR",20,266,&lv_font_montserrat_10,lv_color_hex(RED));lab(s,"Elige tu apariencia",20,284,&lv_font_montserrat_20,lv_color_hex(0xFFFFFF));themebtn(s,"Claro","Mas luminoso",318,false);themebtn(s,"Oscuro","Menos brillo",384,true);}
static void connect_cb(lv_event_t*e){(void)e;flappy_request_wifi_connect(selected,lv_textarea_get_text(pass));lv_obj_t*o=lv_obj_create(lv_scr_act());lv_obj_set_size(o,320,480);lv_obj_set_style_bg_color(o,lv_color_hex(INK),0);lv_obj_set_style_bg_opa(o,LV_OPA_80,0);lv_obj_t*l=lab(o,"Conectando...",0,0,&lv_font_montserrat_14,lv_color_hex(0xFFFFFF));lv_obj_center(l);}
static void net_cb(lv_event_t*e){uint8_t i=(uint8_t)(intptr_t)lv_event_get_user_data(e);if(i>=count)return;strncpy(selected,ssids[i],32);selected[32]=0;if(!secured[i]){flappy_request_wifi_connect(selected,"");return;}lv_obj_t*s=screen();bar(s);lab(s,"CONECTAR A",20,54,&lv_font_montserrat_10,lv_color_hex(RED));lab(s,selected,20,73,&lv_font_montserrat_20,text());pass=lv_textarea_create(s);lv_obj_set_pos(pass,20,115);lv_obj_set_size(pass,280,52);lv_textarea_set_one_line(pass,true);lv_textarea_set_password_mode(pass,true);lv_textarea_set_placeholder_text(pass,"Contrasena");lv_obj_set_style_bg_color(pass,surface(),0);lv_obj_set_style_text_color(pass,text(),0);lv_obj_t*k=lv_keyboard_create(s);lv_obj_set_size(k,320,230);lv_obj_align(k,LV_ALIGN_BOTTOM_MID,0,0);lv_keyboard_set_textarea(k,pass);lv_obj_t*b=lv_btn_create(s);lv_obj_set_size(b,72,34);lv_obj_align(b,LV_ALIGN_TOP_RIGHT,-20,180);btnstyle(b,true);lv_obj_t*l=lv_label_create(b);lv_label_set_text(l,"OK");lv_obj_center(l);lv_obj_add_event_cb(b,connect_cb,LV_EVENT_CLICKED,NULL);}
static void scan_cb(lv_event_t*e){(void)e;ui_wifi_clear();lv_label_set_text(status,"Buscando redes...");flappy_request_wifi_scan();}
static void show_wifi(){lv_obj_t*s=screen();bar(s);head(s,"01 / 03","Conecta tu Flappy","Elige una red Wi-Fi para comenzar.");list=lv_obj_create(s);lv_obj_set_pos(list,16,132);lv_obj_set_size(list,288,250);lv_obj_set_flex_flow(list,LV_FLEX_FLOW_COLUMN);lv_obj_set_style_bg_opa(list,LV_OPA_TRANSP,0);lv_obj_set_style_border_width(list,0,0);lv_obj_set_style_pad_all(list,4,0);status=lab(s,"Buscando redes...",20,397,&lv_font_montserrat_10,muted());lv_obj_t*b=lv_btn_create(s);lv_obj_set_size(b,94,34);lv_obj_align(b,LV_ALIGN_BOTTOM_RIGHT,-20,-15);btnstyle(b,false);lv_obj_t*l=lv_label_create(b);lv_label_set_text(l,"Reintentar");lv_obj_set_style_text_color(l,text(),0);lv_obj_center(l);lv_obj_add_event_cb(b,scan_cb,LV_EVENT_CLICKED,NULL);flappy_request_wifi_scan();}
void ui_wifi_clear(){count=0;if(list)lv_obj_clean(list);}void ui_wifi_add_network(const char*s,int8_t r,bool sec){if(!list||count>=MAX_NET||!s||!*s)return;uint8_t i=count++;strncpy(ssids[i],s,32);ssids[i][32]=0;secured[i]=sec;lv_obj_t*b=lv_btn_create(list);lv_obj_set_width(b,LV_PCT(100));lv_obj_set_height(b,48);btnstyle(b,false);lv_obj_add_event_cb(b,net_cb,LV_EVENT_CLICKED,(void*)(intptr_t)i);lab(b,r>-60?"|||":r>-75?"||":"|",8,11,&lv_font_montserrat_12,lv_color_hex(RED));lab(b,ssids[i],50,8,&lv_font_montserrat_12,text());lab(b,sec?"Protegida":"Abierta",50,25,&lv_font_montserrat_10,muted());}void ui_wifi_scan_complete(){if(status)lv_label_set_text(status,count?"Selecciona una red":"No se encontraron redes");}
static void pick_cb(lv_event_t*e){profile=(const char*)lv_event_get_user_data(e);}static void details_cb(lv_event_t*e){(void)e;show_details();}
