static void ready_cb(lv_event_t*e){(void)e;show_ready();}static void show_companion(){lv_obj_t*s=screen();bar(s);lab(s,"APP COMPANERA",20,145,&lv_font_montserrat_10,lv_color_hex(RED));lab(s,"Siempre cerca,",20,170,&lv_font_montserrat_24,text());lab(s,"incluso a distancia.",20,200,&lv_font_montserrat_24,text());const char*t=strcmp(profile,"Adulto mayor")==0?"Recibe alertas urgentes y confirma que todo esta bien.":"Gestiona ajustes y manten a la familia conectada.";lv_obj_t*l=lab(s,t,20,244,&lv_font_montserrat_12,muted());lv_obj_set_width(l,270);lv_obj_t*sw=lv_switch_create(s);lv_obj_set_pos(sw,20,312);lv_obj_add_state(sw,LV_STATE_CHECKED);lab(s,"Instalar en mi celular",78,316,&lv_font_montserrat_12,text());bottom(s,"Finalizar configuracion",ready_cb);}
